package com.srent.contract;
import com.srent.common.ApiException; import com.srent.config.AppProperties; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.http.*; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient; import java.util.Map;
@Component @ConditionalOnProperty(name="app.providers.contract-mode",havingValue="external")
public class ExternalContractAnalysisProvider implements ContractAnalysisProvider {private final AppProperties p;private final RestClient client=RestClient.create();public ExternalContractAnalysisProvider(AppProperties p){this.p=p;}public Result analyze(String text){var x=p.getProviders();if(x.getContractEndpoint()==null||x.getContractEndpoint().isBlank()||x.getContractApiKey()==null||x.getContractApiKey().isBlank())throw new ApiException(HttpStatus.SERVICE_UNAVAILABLE,"CONTRACT_AI_NOT_CONFIGURED","Provider phân tích hợp đồng chưa có endpoint/API key hợp lệ");try{return client.post().uri(x.getContractEndpoint()).header("Authorization","Bearer "+x.getContractApiKey()).body(Map.of("text",text)).retrieve().body(Result.class);}catch(Exception e){throw new ApiException(HttpStatus.BAD_GATEWAY,"CONTRACT_AI_ERROR","Provider phân tích hợp đồng không phản hồi hợp lệ");}}public String name(){return "EXTERNAL_CONTRACT_ANALYZER";}public boolean simulated(){return false;}}
